const data = $input.first().json;
const keywords = data.keywords || [];
return keywords.map(k => ({ json: k }));

const body = $input.first().json;
const kw = $('Split Keywords').item.json;
const items = body?.items || [];

if (!items.length) return [{ json: { candidates: [], keyword: kw.keyword } }];

const videoIds = items.map(i => i.id?.videoId).filter(Boolean).join(',');
return [{ json: { videoIds, keyword: kw.keyword, category: kw.category || 'drama', items } }];

const details = $input.first().json;
const prev = $('Extract IDs').item.json;
const keyword = prev.keyword || '';
const category = prev.category || 'drama';
const videos = details?.items || [];

function isoToDur(iso) {
  if (!iso) return 0;
  const m = iso.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!m) return 0;
  return (parseInt(m[1]||0)*3600) + (parseInt(m[2]||0)*60) + (parseInt(m[3]||0));
}

function detectOrigin(title) {
  const t = title.toLowerCase();
  if (/تركي|تركية|turkish/.test(t)) return 'turkish';
  if (/هندي|هندية|hindi|bollywood/.test(t)) return 'indian';
  if (/كوري|كورية|korean/.test(t)) return 'korean';
  if (/صيني|صينية|chinese/.test(t)) return 'chinese';
  if (/مغربي|مغربية|maroc|moroccan|darija/.test(t)) return 'moroccan';
  if (/أمريكي|أمريكية|american|english/.test(t)) return 'american';
  return 'other';
}

const MIN_DUR = 2100; // 35 min for films
const TRAILER_RE = /trailer|teaser|تريلر|تيزر|اعلان|إعلان|مقدمة|promo|preview/i;

const candidates = videos
  .filter(v => {
    const dur = isoToDur(v.contentDetails?.duration);
    const embeddable = v.status?.embeddable === true;
    const isPublic = v.status?.privacyStatus === 'public';
    const isLive = v.snippet?.liveBroadcastContent === 'live';
    const title = v.snippet?.title || '';
    const isTrailer = TRAILER_RE.test(title);
    return embeddable && isPublic && !isLive && !isTrailer && dur >= MIN_DUR;
  })
  .map(v => {
    const dur = isoToDur(v.contentDetails?.duration);
    const title = v.snippet?.title || '';
    const year = parseInt(v.snippet?.publishedAt?.slice(0,4)) || null;
    return {
      platform: 'youtube',
      platform_id: v.id,
      title_raw: title,
      type: 'film',
      origin: detectOrigin(title),
      language: 'ar_dubbed',
      category,
      year,
      duration_sec: dur,
      poster_url: v.snippet?.thumbnails?.high?.url || v.snippet?.thumbnails?.medium?.url || null,
      embeddable: true,
      keyword,
      source_workflow: '02-youtube-discover-films'
    };
  });

console.log(`[YT Films] ${keyword} → ${candidates.length} candidates`);
return [{ json: { candidates, keyword } }];
